public static class OshodiGreyboxBuilder
{
    public const string LayoutPath = "docs/specs/oshodi-greybox-layout.json";
    public const string PrefabDir = "Assets/Prefabs/World/Greybox";
    public const string MaterialDir = "Assets/Materials/Greybox";
    public const string DistrictScenePath = "Assets/Scenes/Districts/District_Oshodi_Core.unity";
    public const string ApproachScenePath = "Assets/Scenes/Approach_South.unity";
    public const string GeneratedRootName = "Oshodi_Generated";

    public const int LayerGround = 8;
    public const int LayerBuilding = 9;
    public const int LayerProp = 10;
    public const int LayerCameraIgnore = 11;
    public const int LayerPlayerBlocker = 12;
    public const int LayerMarker = 13;

    // ------------------------------------------------------------ menu items

    [MenuItem("Naija Streets/Build Oshodi Greybox/Build in Open Scene")]
    public static void BuildInOpenScene()
    {
        string path = EditorSceneManager.GetActiveScene().path;
        if (path == ApproachScenePath) BuildApproachSouth();
        else BuildDistrictOshodiCore();
    }

    [MenuItem("Naija Streets/Build Oshodi Greybox/Build District_Oshodi_Core")]
    public static void BuildDistrictOshodiCore()
    {
        LayoutData layout = LoadLayout();
        Scene scene = OpenOrCreateScene(DistrictScenePath);
        RebuildGeneratedRoot(scene, layout, BuildDistrict);
        EnsureSun(scene, 13f);
        EditorSceneManager.SaveScene(scene);
        Debug.Log("[OshodiGreybox] District_Oshodi_Core built: " + layout.buildings.Length +
            " buildings, " + layout.props.Length + " props, " + layout.danfoPark.danfos.Length + " danfos.");
    }

    [MenuItem("Naija Streets/Build Oshodi Greybox/Build Approach_South")]
    public static void BuildApproachSouth()
    {
        LayoutData layout = LoadLayout();
        Scene scene = OpenOrCreateScene(ApproachScenePath);
        RebuildGeneratedRoot(scene, layout, BuildApproach);
        EnsureSun(scene, 13f);
        EditorSceneManager.SaveScene(scene);
        Debug.Log("[OshodiGreybox] Approach_South built.");
    }

    [MenuItem("Naija Streets/Build Oshodi Greybox/Build All Oshodi Scenes")]
    public static void BuildAll()
    {
        BuildDistrictOshodiCore();
        BuildApproachSouth();
    }

