    // ------------------------------------------------------------ loading

    public static LayoutData LoadLayout()
    {
        string full = Path.Combine(Application.dataPath, "../" + LayoutPath);
        string json = File.ReadAllText(full);
        LayoutData layout = JsonUtility.FromJson<LayoutData>(json);
        if (layout == null || layout.buildings == null)
            throw new InvalidOperationException("Failed to parse " + LayoutPath);
        return layout;
    }

    public static Vector3 RectCentre(Rect r) { return new Vector3((r.x0 + r.x1) * 0.5f, 0, (r.z0 + r.z1) * 0.5f); }
    public static float RectWidth(Rect r) { return r.x1 - r.x0; }
    public static float RectDepth(Rect r) { return r.z1 - r.z0; }

    // Yaw for a front: east +X = 90, west -X = 270, south -Z = 180, north +Z = 0.
    public static float FrontYaw(string front)
    {
        if (front == "east") return 90f;
        if (front == "west") return 270f;
        if (front == "south") return 180f;
        return 0f;
    }

    // ------------------------------------------------------------ scene plumbing

    private static Scene OpenOrCreateScene(string path)
    {
        Scene scene = EditorSceneManager.GetActiveScene();
        if (scene.path == path) return scene;
        if (File.Exists(Path.Combine(Application.dataPath, "../" + path)))
            return EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
        Directory.CreateDirectory(Path.GetDirectoryName(Path.Combine(Application.dataPath, "../" + path)));
        scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        EditorSceneManager.SaveScene(scene, path);
        return EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
    }

    private delegate void SceneBuilder(GameObject root, LayoutData layout);

    private static void RebuildGeneratedRoot(Scene scene, LayoutData layout, SceneBuilder build)
    {
        SceneManager.SetActiveScene(scene);
        EnsureLayers();
        EnsureMaterials();
        EnsurePrefabs();
        GameObject old = GameObject.Find(GeneratedRootName);
        if (old != null) UnityEngine.Object.DestroyImmediate(old);
        GameObject root = new GameObject(GeneratedRootName);
        build(root, layout);
        EditorSceneManager.MarkSceneDirty(scene);
    }

    // Sun + fog + ambient, created once outside the generated root (hand-made,
    // not layout-derived). hour is WAT (viewpoints use 13:00 / 17:30 / 21:00).
    private static void EnsureSun(Scene scene, float hour)
    {
        SceneManager.SetActiveScene(scene);
        GameObject sunGo = GameObject.Find("Sun");
        if (sunGo == null)
        {
            sunGo = new GameObject("Sun");
            var sun = sunGo.AddComponent<Light>();
            sun.type = LightType.Directional;
            sun.shadows = LightShadows.Hard;
        }
        var light = sunGo.GetComponent<Light>();
        SetSunForHour(light, sunGo, hour);
        // Lagos haze: linear fog, start 80, end 380 (spec 6.2).
        RenderSettings.fog = true;
        RenderSettings.fogMode = FogMode.Linear;
        RenderSettings.fogStartDistance = 80f;
        RenderSettings.fogEndDistance = 380f;
        RenderSettings.fogColor = new Color(0.85f, 0.83f, 0.78f);
        RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Sky;
        RenderSettings.ambientIntensity = 1f;
    }

    // Sun angle/intensity by WAT hour (fixed table, spec 6.1: sunrise 06:30,
    // sunset 18:30). 13:00 = midday, 17:30 = low warm sun, 21:00 = night.
    public static void SetSunForHour(Light sun, GameObject sunGo, float hour)
    {
        if (hour >= 19f || hour < 6f)
        {
            sun.intensity = 0.15f;
            sun.color = new Color(0.55f, 0.65f, 0.9f);
            sunGo.transform.rotation = Quaternion.Euler(25f, 210f, 0);
            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.12f, 0.13f, 0.18f);
            RenderSettings.fogColor = new Color(0.08f, 0.09f, 0.16f);
        }
        else if (hour >= 16.5f)
        {
            sun.intensity = 0.8f;
            sun.color = new Color(1f, 0.6f, 0.35f);
            sunGo.transform.rotation = Quaternion.Euler(12f, 260f, 0);
            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.35f, 0.3f, 0.3f);
            RenderSettings.fogColor = new Color(0.85f, 0.7f, 0.55f);
        }
        else
        {
            sun.intensity = 1.2f;
            sun.color = new Color(1f, 0.97f, 0.9f);
            sunGo.transform.rotation = Quaternion.Euler(55f, 150f, 0);
            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Sky;
            RenderSettings.ambientIntensity = 1f;
            RenderSettings.fogColor = new Color(0.85f, 0.83f, 0.78f);
        }
    }

    private static void EnsureLayers()
    {
        var tagManager = new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);
        SerializedProperty layers = tagManager.FindProperty("layers");
        SetLayer(layers, LayerGround, "Ground");
        SetLayer(layers, LayerBuilding, "Building");
        SetLayer(layers, LayerProp, "Prop");
        SetLayer(layers, LayerCameraIgnore, "CameraIgnore");
        SetLayer(layers, LayerPlayerBlocker, "PlayerBlocker");
        SetLayer(layers, LayerMarker, "Marker");
        tagManager.ApplyModifiedProperties();
    }

    private static void SetLayer(SerializedProperty layers, int index, string name)
    {
        SerializedProperty sp = layers.GetArrayElementAtIndex(index);
        if (string.IsNullOrEmpty(sp.stringValue)) sp.stringValue = name;
        else if (sp.stringValue != name)
            Debug.LogWarning("[OshodiGreybox] Layer " + index + " is '" + sp.stringValue + "', expected '" + name + "'");
    }

