    private static void EnsureMaterials()
    {
        Directory.CreateDirectory(Path.Combine(Application.dataPath, "Materials/Greybox"));
        Mats.Clear();
        foreach (var def in MaterialDefs)
        {
            string path = MaterialDir + "/" + def.Item1 + ".mat";
            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                mat.color = def.Item2;
                mat.SetFloat("_Smoothness", def.Item3);
                mat.SetFloat("_Metallic", def.Item4);
                mat.enableInstancing = true;
                AssetDatabase.CreateAsset(mat, path);
            }
            if (def.Item1 == "Glass" || def.Item1 == "DanfoGlass")
            {
                mat.SetFloat("_Surface", 1f); // transparent
                mat.SetFloat("_Blend", 0f);
                mat.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
                mat.SetFloat("_DstBlend", (float)BlendMode.OneMinusSrcAlpha);
                mat.SetFloat("_ZWrite", 0f);
                mat.DisableKeyword("_ALPHATEST_ON");
                mat.EnableKeyword("_ALPHABLEND_ON");
                mat.DisableKeyword("_ALPHAPREMULTIPLY_ON");
                mat.renderQueue = (int)RenderQueue.Transparent;
                Color c = mat.color; c.a = 0.55f; mat.color = c;
            }
            if (def.Item1 == "LampHead")
            {
                mat.EnableKeyword("_EMISSION");
                mat.SetColor("_EmissionColor", new Color(1f, 0.85f, 0.5f) * 1.5f);
            }
            Mats[def.Item1] = mat;
        }
        AssetDatabase.SaveAssets();
    }

    public static Material GetMat(string name)
    {
        if (Mats.TryGetValue(name, out Material m)) return m;
        Material loaded = AssetDatabase.LoadAssetAtPath<Material>(MaterialDir + "/" + name + ".mat");
        if (loaded == null) throw new InvalidOperationException("Greybox material missing: " + name);
        Mats[name] = loaded;
        return loaded;
    }

    // ------------------------------------------------------------ mesh builder

    // Accumulates boxes (axis-aligned or rotated) into per-material submeshes.
    // One MeshBuilder = one mesh = one draw call per submesh. All boxes are
    // opaque, hard-edged greybox: flat normals, no UVs needed (flat colours).
    public class MeshBuilder
    {
        private readonly Dictionary<int, List<Vector3>> _verts = new Dictionary<int, List<Vector3>>();
        private readonly Dictionary<int, List<Vector3>> _normals = new Dictionary<int, List<Vector3>>();
        private readonly Dictionary<int, List<int>> _tris = new Dictionary<int, List<int>>();

        private List<Vector3> V(int mat) { if (!_verts.TryGetValue(mat, out var l)) { l = new List<Vector3>(); _verts[mat] = l; } return l; }
        private List<Vector3> N(int mat) { if (!_normals.TryGetValue(mat, out var l)) { l = new List<Vector3>(); _normals[mat] = l; } return l; }
        private List<int> T(int mat) { if (!_tris.TryGetValue(mat, out var l)) { l = new List<int>(); _tris[mat] = l; } return l; }

        private static readonly Vector3[] BoxCorners =
        {
            new Vector3(-0.5f, -0.5f, -0.5f), new Vector3(0.5f, -0.5f, -0.5f),
            new Vector3(0.5f, 0.5f, -0.5f), new Vector3(-0.5f, 0.5f, -0.5f),
            new Vector3(-0.5f, -0.5f, 0.5f), new Vector3(0.5f, -0.5f, 0.5f),
            new Vector3(0.5f, 0.5f, 0.5f), new Vector3(-0.5f, 0.5f, 0.5f),
        };

        private static readonly int[][] BoxFaces =
        {
            new[] { 4, 5, 6, 7 }, new[] { 1, 0, 3, 2 }, // +Z, -Z
            new[] { 5, 1, 2, 6 }, new[] { 0, 4, 7, 3 }, // +X, -X
            new[] { 7, 6, 2, 3 }, new[] { 0, 1, 5, 4 }, // +Y, -Y
        };

        private static readonly Vector3[] BoxNormals =
        {
            Vector3.forward, Vector3.back, Vector3.right, Vector3.left, Vector3.up, Vector3.down,
        };

        public void AddBox(Vector3 center, Vector3 size, Quaternion rotation, int mat)
        {
            var verts = V(mat); var normals = N(mat); var tris = T(mat);
            int baseIndex = verts.Count;
            for (int f = 0; f < 6; f++)
            {
                for (int i = 0; i < 4; i++)
                {
                    Vector3 c = BoxCorners[BoxFaces[f][i]];
                    Vector3 p = new Vector3(c.x * size.x, c.y * size.y, c.z * size.z);
                    verts.Add(center + rotation * p);
                    normals.Add(rotation * BoxNormals[f]);
                }
                tris.Add(baseIndex + f * 4 + 0);
                tris.Add(baseIndex + f * 4 + 1);
                tris.Add(baseIndex + f * 4 + 2);
                tris.Add(baseIndex + f * 4 + 0);
                tris.Add(baseIndex + f * 4 + 2);
                tris.Add(baseIndex + f * 4 + 3);
            }
        }

        public void AddBox(Vector3 center, Vector3 size, int mat)
        {
            AddBox(center, size, Quaternion.identity, mat);
        }

        // Axis-aligned box from a layout rect, y0 (bottom) to y1 (top).
        public void AddRectBox(Rect r, float y0, float y1, int mat)
        {
            AddBox(new Vector3((r.x0 + r.x1) * 0.5f, (y0 + y1) * 0.5f, (r.z0 + r.z1) * 0.5f),
                new Vector3(r.x1 - r.x0, y1 - y0, r.z1 - r.z0), mat);
        }

        // Flat quad (top face only) over a layout rect at height y.
        public void AddRectQuad(Rect r, float y, int mat)
        {
            var verts = V(mat); var normals = N(mat); var tris = T(mat);
            int b = verts.Count;
            verts.Add(new Vector3(r.x0, y, r.z0));
            verts.Add(new Vector3(r.x1, y, r.z0));
            verts.Add(new Vector3(r.x1, y, r.z1));
            verts.Add(new Vector3(r.x0, y, r.z1));
            for (int i = 0; i < 4; i++) normals.Add(Vector3.up);
            tris.Add(b); tris.Add(b + 1); tris.Add(b + 2);
            tris.Add(b); tris.Add(b + 2); tris.Add(b + 3);
        }

        // Curved wall: an arc of `segments` quads, chord `width`, bulge `sagitta`,
        // height `height`, base at y=0, arc bulging toward +Z. Used for the
        // terminal curved-glass front (spec 4.1, 6-8 segments).
        public static Mesh BuildArcWall(float width, float sagitta, float height, int segments)
        {
            float r = (sagitta * sagitta + width * width * 0.25f) / (2f * sagitta);
            float cy = r - sagitta;
            float halfAngle = Mathf.Asin(width * 0.5f / r);
            var verts = new List<Vector3>();
            var normals = new List<Vector3>();
            var tris = new List<int>();
            for (int i = 0; i <= segments; i++)
            {
                float a = -halfAngle + 2f * halfAngle * i / segments;
                Vector3 dir = new Vector3(Mathf.Sin(a), 0, Mathf.Cos(a));
                Vector3 p = new Vector3(dir.x * r, 0, cy + dir.z * r - r + sagitta);
                verts.Add(new Vector3(p.x, 0, p.z));
                verts.Add(new Vector3(p.x, height, p.z));
                normals.Add(dir);
                normals.Add(dir);
            }
            for (int i = 0; i < segments; i++)
            {
                int b = i * 2;
                tris.Add(b); tris.Add(b + 1); tris.Add(b + 2);
                tris.Add(b + 1); tris.Add(b + 3); tris.Add(b + 2);
            }
            var mesh = new Mesh { name = "ArcWall" };
            mesh.SetVertices(verts);
            mesh.SetNormals(normals);
            mesh.SetTriangles(tris, 0);
            mesh.RecalculateBounds();
            return mesh;
        }

        public Mesh Build(string name)
        {
            var mesh = new Mesh { name = name };
            var allVerts = new List<Vector3>();
            var allNormals = new List<Vector3>();
            var mats = new List<int>(_tris.Keys);
            mats.Sort();
            mesh.subMeshCount = mats.Count;
            for (int s = 0; s < mats.Count; s++)
            {
                int mat = mats[s];
                int offset = allVerts.Count;
                allVerts.AddRange(_verts[mat]);
                allNormals.AddRange(_normals[mat]);
                int[] sub = _tris[mat].ToArray();
                for (int i = 0; i < sub.Length; i++) sub[i] += offset;
                mesh.SetTriangles(sub, s);
            }
            mesh.SetVertices(allVerts);
            mesh.SetNormals(allNormals);
            mesh.RecalculateBounds();
            return mesh;
        }
    }

    // Cylinder along Y, diameter d, height h, centred at origin.
    public static Mesh BuildCylinderMesh(float d, float h, int segments)
    {
        float r = d * 0.5f;
        var verts = new List<Vector3>();
        var normals = new List<Vector3>();
        var tris = new List<int>();
        for (int i = 0; i <= segments; i++)
        {
            float a = 2f * Mathf.PI * i / segments;
            Vector3 n = new Vector3(Mathf.Sin(a), 0, Mathf.Cos(a));
            verts.Add(new Vector3(r * n.x, -h * 0.5f, r * n.z)); normals.Add(n);
            verts.Add(new Vector3(r * n.x, h * 0.5f, r * n.z)); normals.Add(n);
        }
        for (int i = 0; i < segments; i++)
        {
            int b = i * 2;
            tris.Add(b); tris.Add(b + 1); tris.Add(b + 2);
            tris.Add(b + 1); tris.Add(b + 3); tris.Add(b + 2);
        }
        // Top and bottom caps (triangle fans).
        int topCenter = verts.Count;
        verts.Add(new Vector3(0, h * 0.5f, 0)); normals.Add(Vector3.up);
        int botCenter = verts.Count;
        verts.Add(new Vector3(0, -h * 0.5f, 0)); normals.Add(Vector3.down);
        for (int i = 0; i < segments; i++)
        {
            float a0 = 2f * Mathf.PI * i / segments;
            float a1 = 2f * Mathf.PI * (i + 1) / segments;
            int t0 = verts.Count; verts.Add(new Vector3(r * Mathf.Sin(a0), h * 0.5f, r * Mathf.Cos(a0))); normals.Add(Vector3.up);
            int t1 = verts.Count; verts.Add(new Vector3(r * Mathf.Sin(a1), h * 0.5f, r * Mathf.Cos(a1))); normals.Add(Vector3.up);
            tris.Add(topCenter); tris.Add(t0); tris.Add(t1);
            int b0 = verts.Count; verts.Add(new Vector3(r * Mathf.Sin(a0), -h * 0.5f, r * Mathf.Cos(a0))); normals.Add(Vector3.down);
            int b1 = verts.Count; verts.Add(new Vector3(r * Mathf.Sin(a1), -h * 0.5f, r * Mathf.Cos(a1))); normals.Add(Vector3.down);
            tris.Add(botCenter); tris.Add(b1); tris.Add(b0);
        }
        var mesh = new Mesh { name = "Cylinder" };
        mesh.SetVertices(verts);
        mesh.SetNormals(normals);
        mesh.SetTriangles(tris, 0);
        mesh.RecalculateBounds();
        return mesh;
    }

    // Annulus (flat ring) in the XZ plane at height y, inner radius r0, outer r1.
    public static Mesh BuildAnnulusMesh(float r0, float r1, float y, int segments)
    {
        var verts = new List<Vector3>();
        var normals = new List<Vector3>();
        var tris = new List<int>();
        for (int i = 0; i <= segments; i++)
        {
            float a = 2f * Mathf.PI * i / segments;
            float c = Mathf.Cos(a), s = Mathf.Sin(a);
            verts.Add(new Vector3(r0 * s, y, r0 * c)); normals.Add(Vector3.up);
            verts.Add(new Vector3(r1 * s, y, r1 * c)); normals.Add(Vector3.up);
        }
        for (int i = 0; i < segments; i++)
        {
            int b = i * 2;
            tris.Add(b); tris.Add(b + 2); tris.Add(b + 1);
            tris.Add(b + 1); tris.Add(b + 2); tris.Add(b + 3);
        }
        var mesh = new Mesh { name = "Annulus" };
        mesh.SetVertices(verts);
        mesh.SetNormals(normals);
        mesh.SetTriangles(tris, 0);
        mesh.RecalculateBounds();
        return mesh;
    }

    // Quadratic bezier tube (thin boxes) from a to b with control point ctrl.
    // Used for NEPA wires: the control point sits below the chord so the wire
    // sags. For a wire with endpoints at topY sagging to sagY at mid, the
    // control y is 2*sagY - topY (quadratic midpoint = (a + 2*ctrl + b) / 4).
    public static void AddQuadraticBezier(MeshBuilder mb, Vector3 a, Vector3 ctrl, Vector3 b, int mat, int steps)
    {
        Vector3 prev = a;
        for (int i = 1; i <= steps; i++)
        {
            float t = (float)i / steps;
            float u = 1f - t;
            Vector3 p = u * u * a + 2f * u * t * ctrl + t * t * b;
            Vector3 mid = (prev + p) * 0.5f;
            Vector3 dir = (p - prev).normalized;
            float len = (p - prev).magnitude + 0.02f;
            Quaternion rot = Quaternion.LookRotation(dir);
            mb.AddBox(mid, new Vector3(0.03f, 0.03f, len), rot, mat);
            prev = p;
        }
    }

    // ------------------------------------------------------------ prefabs

    private static void SetMesh(GameObject go, Mesh mesh, params Material[] materials)
    {
        var mf = go.AddComponent<MeshFilter>();
        mf.sharedMesh = mesh;
        var mr = go.AddComponent<MeshRenderer>();
        mr.sharedMaterials = materials;
        mr.shadowCastingMode = ShadowCastingMode.On;
        mr.receiveShadows = true;
        go.isStatic = true;
    }

    private static void AddBoxCollider(GameObject go, Vector3 center, Vector3 size)
    {
        var c = go.AddComponent<BoxCollider>();
        c.center = center;
        c.size = size;
    }

    private static void AddCapsuleCollider(GameObject go, Vector3 center, float radius, float height)
    {
        var c = go.AddComponent<CapsuleCollider>();
        c.center = center;
        c.radius = radius;
        c.height = height;
    }

    private static GameObject SavePrefab(string typeName, Action<GameObject> build)
    {
        string path = PrefabDir + "/Greybox_" + typeName + ".prefab";
        var temp = new GameObject("Greybox_" + typeName);
        try
        {
            build(temp);
            GameObject prefab = PrefabUtility.SaveAsPrefabAsset(temp, path);
            if (prefab == null) throw new InvalidOperationException("SaveAsPrefabAsset failed: " + path);
            return prefab;
        }
        finally { UnityEngine.Object.DestroyImmediate(temp); }
    }

    private static GameObject LoadPrefab(string typeName)
    {
        string path = PrefabDir + "/Greybox_" + typeName + ".prefab";
        GameObject p = AssetDatabase.LoadAssetAtPath<GameObject>(path);
        if (p == null) throw new InvalidOperationException("Prefab missing, run EnsurePrefabs first: " + path);
        return p;
    }

    private static void EnsurePrefabs()
    {
        Directory.CreateDirectory(Path.Combine(Application.dataPath, "Prefabs/World/Greybox"));
        EnsureMaterials();
        BuildTerminalPrefab();
        BuildShophousePrefab();
        BuildFillerPrefab();
        BuildDanfoPrefab();
        BuildOkadaPrefab();
        BuildNepaPolePrefab();
        BuildStreetLampPrefab();
        BuildSoffitLampPrefab();
        BuildStallPrefabs();
        BuildUmbrellaPrefabs();
        BuildBusShelterPrefab();
        BuildBusStopPolePrefab();
        BuildStreetSignPrefab();
        BuildRouteBoardPrefab();
        BuildGeneratorPrefab();
        BuildPosKioskPrefab();
        BuildTreePrefab();
        BuildTyreStackPrefab();
        BuildCarShellPrefab();
        BuildHoardingPrefab();
        BuildPosterPrefab();
        BuildFlyoverPierPrefab();
        AssetDatabase.SaveAssets();
    }

    // Unit terminal (1 x 1 x 1, front = +Z): concrete box, curved glass front,
    // floor bands, 3 dark door recesses, front step. Instances are scaled to
    // footprint x height. The name sign is added by the scene builder in WORLD
    // space (text would distort under the instance's non-uniform scale).
    private static void BuildTerminalPrefab()
    {
        if (AssetDatabase.LoadAssetAtPath<GameObject>(PrefabDir + "/Greybox_Terminal.prefab") != null) return;
        SavePrefab("Terminal", root =>
        {
            var mb = new MeshBuilder();
            // 0 Concrete, 1 ShopFront (doors), 2 SteelDark (bands/step)
            mb.AddBox(Vector3.zero, Vector3.one, Quaternion.identity, 0);
            mb.AddBox(new Vector3(0, 0.33f, 0.505f), new Vector3(1f, 0.05f, 0.02f), 0, 2);
            mb.AddBox(new Vector3(0, 0.66f, 0.505f), new Vector3(1f, 0.05f, 0.02f), 0, 2);
            mb.AddBox(new Vector3(-0.28f, 0.125f, 0.505f), new Vector3(0.22f, 0.25f, 0.02f), 0, 1);
            mb.AddBox(new Vector3(0, 0.125f, 0.505f), new Vector3(0.22f, 0.25f, 0.02f), 0, 1);
            mb.AddBox(new Vector3(0.28f, 0.125f, 0.505f), new Vector3(0.22f, 0.25f, 0.02f), 0, 1);
            mb.AddBox(new Vector3(0, 0.0125f, 0.55f), new Vector3(1f, 0.025f, 0.1f), 0, 2);
            SetMesh(root, mb.Build("TerminalBody"),
                GetMat("Concrete"), GetMat("ShopFront"), GetMat("SteelDark"));
            var glass = new GameObject("GlassFront");
            glass.transform.SetParent(root.transform, false);
            glass.transform.localPosition = new Vector3(0, 0, 0.5f);
            Mesh arc = MeshBuilder.BuildArcWall(1f, 0.12f, 1f, 6);
            var gmf = glass.AddComponent<MeshFilter>(); gmf.sharedMesh = arc;
            var gmr = glass.AddComponent<MeshRenderer>(); gmr.sharedMaterial = GetMat("Glass");
            gmr.shadowCastingMode = ShadowCastingMode.Off;
            glass.isStatic = true;
            AddBoxCollider(root, Vector3.zero, Vector3.one);
            root.layer = LayerBuilding;
        });
    }

