    // One prefab per awning colour; the builder picks by row (r1 red, r2 blue, r3 yellow).
    // A bare bulb (emissive) hangs under each awning (spec 4.4).
    private static void BuildStallPrefabs()
    {
        string[] colours = { "Red", "Blue", "Yellow" };
        string[] mats = { "StallRed", "StallBlue", "StallYellow" };
        for (int i = 0; i < 3; i++)
        {
            string type = "Stall" + colours[i];
            if (AssetDatabase.LoadAssetAtPath<GameObject>(PrefabDir + "/Greybox_" + type + ".prefab") != null) continue;
            Material canvas = GetMat(mats[i]);
            SavePrefab(type, root =>
            {
                var mb = new MeshBuilder();
                // 0 StallTable, 1 canvas, 2 LampHead (bulb)
                mb.AddBox(new Vector3(0, 0.45f, 0), new Vector3(1.9f, 0.85f, 1.9f), 0, 0);
                mb.AddBox(new Vector3(0, 0.92f, 0), new Vector3(2f, 0.06f, 2f), 0, 0);
                for (int px = -1; px <= 1; px += 2)
                    for (int pz = -1; pz <= 1; pz += 2)
                        mb.AddBox(new Vector3(px * 0.95f, 1.1f, pz * 0.95f), new Vector3(0.06f, 2.2f, 0.06f), 0, 0);
                mb.AddBox(new Vector3(0, 2.25f, 0), new Vector3(2.2f, 0.06f, 2.2f), 0, 1);
                mb.AddBox(new Vector3(0, 2.1f, 0), new Vector3(0.12f, 0.12f, 0.12f), 0, 2);
                SetMesh(root, mb.Build(type), GetMat("StallTable"), canvas, GetMat("LampHead"));
                AddBoxCollider(root, new Vector3(0, 1.2f, 0), new Vector3(2f, 2.4f, 2f));
                root.layer = LayerProp;
            });
        }
    }

