    // ------------------------------------------------------------ district scene

    private static void BuildDistrict(GameObject root, LayoutData layout)
    {
        BuildGround(root, layout);
        BuildBuildings(root, layout);
        BuildProps(root, layout);
        BuildDanfoPark(root, layout);
        BuildOkadaPark(root, layout);
        BuildFlyover(root, layout);
        BuildFootbridge(root, layout);
        BuildWires(root, layout);
        BuildSkyline(root, new Vector3(0, 0, 0), 350f);
        BuildBlockers(root, layout);
        BuildMarkers(root, layout);
    }

    // ------------------------------------------------------------ ground

    private static void BuildGround(GameObject root, LayoutData layout)
    {
        // Base plane under everything (dirt, top y=-0.02 so it never z-fights
        // the road tops at y=0). Fills the gaps between buildings/plots.
        var baseMb = new MeshBuilder();
        baseMb.AddBox(new Vector3(0, -0.51f, 0), new Vector3(240f, 1f, 300f), 0, 0);
        var baseGo = new GameObject("GroundBase");
        baseGo.transform.SetParent(root.transform, false);
        SetMesh(baseGo, baseMb.Build("GroundBase"), GetMat("Dirt"));
        baseGo.layer = LayerGround;
        AddGroundBox(baseGo, 0, -0.02f, 0, 240f, 1f, 300f);

        // Roads (asphalt, top y=0): lane rects + junction + driveways + park
        // pad/aisles/lanes. One merged mesh, one draw call.
        var roadMb = new MeshBuilder();
        var roadGo = new GameObject("Roads");
        roadGo.transform.SetParent(root.transform, false);
        foreach (var lane in layout.lanes)
        {
            roadMb.AddRectBox(lane.r, -0.5f, 0f, 0);
            AddGroundBox(roadGo, (lane.r.x0 + lane.r.x1) * 0.5f, 0f, (lane.r.z0 + lane.r.z1) * 0.5f,
                lane.r.x1 - lane.r.x0, 0.5f, lane.r.z1 - lane.r.z0);
        }
        foreach (var d in layout.driveways)
            roadMb.AddRectBox(d.r, -0.5f, 0f, 0);
        roadMb.AddRectBox(layout.danfoPark.pad, -0.5f, 0f, 0);
        roadMb.AddRectBox(layout.danfoPark.tailAisle, -0.5f, 0f, 0);
        roadMb.AddRectBox(layout.danfoPark.headAisle, -0.5f, 0f, 0);
        foreach (var lane in layout.danfoPark.loadingLanes)
            roadMb.AddRectBox(lane.r, -0.5f, 0f, 0);
        // The roads carry on 10 m past the tile edge (spec 2), then the blocker wall.
        roadMb.AddRectBox(new Rect { x0 = -7.55f, z0 = 150f, x1 = 7.55f, z1 = 160f }, -0.5f, 0f, 0);
        roadMb.AddRectBox(new Rect { x0 = -7.55f, z0 = -160f, x1 = 7.55f, z1 = -150f }, -0.5f, 0f, 0);
        roadMb.AddRectBox(new Rect { x0 = -130f, z0 = -73.25f, x1 = -120f, z1 = -66.75f }, -0.5f, 0f, 0);
        roadMb.AddRectBox(new Rect { x0 = 120f, z0 = -73.25f, x1 = 130f, z1 = -66.75f }, -0.5f, 0f, 0);
        SetMesh(roadGo, roadMb.Build("Roads"), GetMat("Asphalt"));
        roadGo.layer = LayerGround;

        // Markings (white, y=0.02): ROAD-B centre dashes, zebra stripes
        // (junction crossings + park walk crossings), flyover deck lane lines.
        // Submesh 1 (DarkLine): gutter slab joints every 1 m (spec 3.4).
        var markMb = new MeshBuilder();
        var markGo = new GameObject("RoadMarkings");
        markGo.transform.SetParent(root.transform, false);
        // ROAD-B centre dashes (along X at z=-70, 3 m dash / 3 m gap).
        for (float x = -118f; x < 118f; x += 6f)
            markMb.AddBox(new Vector3(x, 0.02f, -70f), new Vector3(3f, 0.02f, 0.2f), 0, 0);
        // Zebra stripes: 0.5 m bars, 0.5 m gaps, across each crossing rect.
        foreach (var c in layout.crossings)
            AddZebra(markMb, c.r, 0);
        foreach (var w in layout.danfoPark.walkCrossings)
            AddZebra(markMb, w.r, 0);
        // Flyover deck lane lines (3 lanes each way, dashed, at deck top 7.2).
        for (int li = 0; li < 5; li++)
        {
            float z = 37.6f + li * 3.6f;
            for (float x = -118f; x < 118f; x += 6f)
                markMb.AddBox(new Vector3(x, 7.22f, z), new Vector3(3f, 0.02f, 0.2f), 0, 0);
        }
        // Gutter joints: dark lines across each gutter every 1 m.
        foreach (var p in layout.pavements)
        {
            AddGutterJoints(markMb, p.gutter);
            AddGutterJoints(markMb, p.furnishing);
        }
        SetMesh(markGo, markMb.Build("RoadMarkings"), GetMat("Marking"), GetMat("DarkLine"));
        markGo.layer = LayerGround;

        // Kerbs + medians (Kerb material, raised 0.12). Medians get colliders.
        var kerbMb = new MeshBuilder();
        var kerbGo = new GameObject("Kerbs");
        kerbGo.transform.SetParent(root.transform, false);
        foreach (var m in layout.medians)
        {
            kerbMb.AddRectBox(m.r, 0f, 0.12f, 0);
            AddGroundBox(kerbGo, (m.r.x0 + m.r.x1) * 0.5f, 0.12f, (m.r.z0 + m.r.z1) * 0.5f,
                m.r.x1 - m.r.x0, 0.12f, m.r.z1 - m.r.z0);
        }
        // Kerb strips along ROAD-A (x +/-7.55..7.7) and ROAD-B (z -73.25..-73.4 / -66.6..-66.75).
        kerbMb.AddRectBox(new Rect { x0 = -7.7f, z0 = -150f, x1 = -7.55f, z1 = 150f }, 0f, 0.12f, 0);
        kerbMb.AddRectBox(new Rect { x0 = 7.55f, z0 = -150f, x1 = 7.7f, z1 = 150f }, 0f, 0.12f, 0);
        kerbMb.AddRectBox(new Rect { x0 = -120f, z0 = -73.4f, x1 = 120f, z1 = -73.25f }, 0f, 0.12f, 0);
        kerbMb.AddRectBox(new Rect { x0 = -120f, z0 = -66.75f, x1 = 120f, z1 = -66.6f }, 0f, 0.12f, 0);
        SetMesh(kerbGo, kerbMb.Build("Kerbs"), GetMat("Kerb"));
        kerbGo.layer = LayerGround;

        // Pavements (Sidewalk, top y=0.12): gutter + furnishing + clear zones
        // + junction corners. One collider per pavement (union rect).
        var paveMb = new MeshBuilder();
        var paveGo = new GameObject("Pavements");
        paveGo.transform.SetParent(root.transform, false);
        foreach (var p in layout.pavements)
        {
            paveMb.AddRectBox(p.gutter, 0f, 0.12f, 0);
            paveMb.AddRectBox(p.furnishing, 0f, 0.12f, 0);
            paveMb.AddRectBox(p.clear, 0f, 0.12f, 0);
            float x0 = Mathf.Min(p.gutter.x0, Mathf.Min(p.furnishing.x0, p.clear.x0));
            float x1 = Mathf.Max(p.gutter.x1, Mathf.Max(p.furnishing.x1, p.clear.x1));
            float z0 = Mathf.Min(p.gutter.z0, Mathf.Min(p.furnishing.z0, p.clear.z0));
            float z1 = Mathf.Max(p.gutter.z1, Mathf.Max(p.furnishing.z1, p.clear.z1));
            AddGroundBox(paveGo, (x0 + x1) * 0.5f, 0.12f, (z0 + z1) * 0.5f, x1 - x0, 0.12f, z1 - z0);
        }
        foreach (var c in layout.corners)
            paveMb.AddRectBox(c.r, 0f, 0.12f, 0);
        SetMesh(paveGo, paveMb.Build("Pavements"), GetMat("Sidewalk"));
        paveGo.layer = LayerGround;

        // Plazas / areas / park islands (top y=0.12). Yard-mechanic is dirt.
        var plazaMb = new MeshBuilder();
        var plazaGo = new GameObject("Plazas");
        plazaGo.transform.SetParent(root.transform, false);
        foreach (var a in layout.areas)
        {
            int mat = a.id == "yard-mechanic" ? 1 : 0;
            plazaMb.AddRectBox(a.r, 0f, 0.12f, mat);
            AddGroundBox(plazaGo, (a.r.x0 + a.r.x1) * 0.5f, 0.12f, (a.r.z0 + a.r.z1) * 0.5f,
                a.r.x1 - a.r.x0, 0.12f, a.r.z1 - a.r.z0);
        }
        foreach (var island in layout.danfoPark.islands)
        {
            plazaMb.AddRectBox(island.r, 0f, island.y, 0);
            AddGroundBox(plazaGo, (island.r.x0 + island.r.x1) * 0.5f, island.y, (island.r.z0 + island.r.z1) * 0.5f,
                island.r.x1 - island.r.x0, island.y, island.r.z1 - island.r.z0);
        }
        SetMesh(plazaGo, plazaMb.Build("Plazas"), GetMat("Sidewalk"), GetMat("Dirt"));
        plazaGo.layer = LayerGround;
    }

    private static void AddGroundBox(GameObject go, float cx, float topY, float cz, float sx, float sy, float sz)
    {
        var c = go.AddComponent<BoxCollider>();
        c.center = new Vector3(cx, topY - sy * 0.5f, cz);
        c.size = new Vector3(sx, sy, sz);
    }

    // Zebra crossing: 0.5 m white bars with 0.5 m gaps, running along the
    // crossing rect's long axis, at y=0.02.
    private static void AddZebra(MeshBuilder mb, Rect r, int mat)
    {
        float w = r.x1 - r.x0, d = r.z1 - r.z0;
        if (w >= d)
        {
            for (float x = r.x0 + 0.25f; x < r.x1; x += 1f)
                mb.AddBox(new Vector3(x, 0.02f, (r.z0 + r.z1) * 0.5f), new Vector3(0.5f, 0.02f, d), 0, mat);
        }
        else
        {
            for (float z = r.z0 + 0.25f; z < r.z1; z += 1f)
                mb.AddBox(new Vector3((r.x0 + r.x1) * 0.5f, 0.02f, z), new Vector3(w, 0.02f, 0.5f), 0, mat);
        }
    }

    // Gutter slab joints: dark lines across the gutter every 1 m (spec 3.4).
    private static void AddGutterJoints(MeshBuilder mb, Rect r)
    {
        float w = r.x1 - r.x0, d = r.z1 - r.z0;
        if (d >= w)
        {
            for (float z = r.z0 + 0.5f; z < r.z1; z += 1f)
                mb.AddBox(new Vector3((r.x0 + r.x1) * 0.5f, 0.125f, z), new Vector3(w, 0.02f, 0.03f), 0, 1);
        }
        else
        {
            for (float x = r.x0 + 0.5f; x < r.x1; x += 1f)
                mb.AddBox(new Vector3(x, 0.125f, (r.z0 + r.z1) * 0.5f), new Vector3(0.03f, 0.02f, d), 0, 1);
        }
    }

    // ------------------------------------------------------------ buildings

    private static void BuildBuildings(GameObject root, LayoutData layout)
    {
        GameObject buildingsGo = new GameObject("Buildings");
        buildingsGo.transform.SetParent(root.transform, false);
        GameObject prefabTerminal = LoadPrefab("Terminal");
        GameObject prefabShop = LoadPrefab("Shophouse");
        GameObject prefabFiller = LoadPrefab("Filler");
        foreach (var b in layout.buildings)
        {
            GameObject prefab = b.kind == "terminal" ? prefabTerminal
                : b.kind == "shophouse" ? prefabShop : prefabFiller;
            GameObject go = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
            go.name = b.id;
            go.transform.SetParent(buildingsGo.transform, false);
            Vector3 centre = RectCentre(b.r);
            go.transform.position = new Vector3(centre.x, 0, centre.z);
            float ry = FrontYaw(b.front);
            go.transform.rotation = Quaternion.Euler(0, ry, 0);
            // Non-uniform scale is applied in local space, then rotated: a 90/270
            // degree yaw swaps the world X/Z extents, so swap the scale to keep
            // the world footprint equal to the rect.
            bool swapped = Mathf.Approximately(ry, 90f) || Mathf.Approximately(ry, 270f);
            float sx = swapped ? RectDepth(b.r) : RectWidth(b.r);
            float sz = swapped ? RectWidth(b.r) : RectDepth(b.r);
            go.transform.localScale = new Vector3(sx, b.h, sz);
            if (b.kind == "terminal" && !string.IsNullOrEmpty(b.name))
                AddTerminalSign(buildingsGo, b);
        }
    }

    // Terminal name sign: a white strip + TMP text on the front face, in WORLD
    // space (the instance is non-uniformly scaled, so a TMP child would distort).
    private static void AddTerminalSign(GameObject parent, BuildingData b)
    {
        float frontWidth = b.front == "east" || b.front == "west" ? RectDepth(b.r) : RectWidth(b.r);
        float cx = (b.r.x0 + b.r.x1) * 0.5f;
        float cz = (b.r.z0 + b.r.z1) * 0.5f;
        float y = b.h * 0.85f;
        float ry = FrontYaw(b.front);
        Vector3 pos;
        Vector3 stripSize;
        if (b.front == "east") { pos = new Vector3(b.r.x1 + 0.06f, y, cz); stripSize = new Vector3(0.1f, 1.6f, frontWidth * 0.9f); }
        else if (b.front == "west") { pos = new Vector3(b.r.x0 - 0.06f, y, cz); stripSize = new Vector3(0.1f, 1.6f, frontWidth * 0.9f); }
        else if (b.front == "south") { pos = new Vector3(cx, y, b.r.z0 - 0.06f); stripSize = new Vector3(frontWidth * 0.9f, 1.6f, 0.1f); }
        else { pos = new Vector3(cx, y, b.r.z1 + 0.06f); stripSize = new Vector3(frontWidth * 0.9f, 1.6f, 0.1f); }
        var strip = new GameObject(b.id + "_SignStrip");
        strip.transform.SetParent(parent.transform, false);
        strip.transform.position = pos;
        strip.transform.rotation = Quaternion.Euler(0, ry, 0);
        var mb = new MeshBuilder();
        mb.AddBox(Vector3.zero, stripSize, Quaternion.identity, 0);
        SetMesh(strip, mb.Build(b.id + "_SignStrip"), GetMat("SignWhite"));
        strip.layer = LayerCameraIgnore;
        // Text sits 0.02 m off the strip face.
        Vector3 textPos = strip.transform.TransformPoint(new Vector3(0, 0, 0.08f));
        AddSignTextWorld(parent, b.name, textPos, ry, 1.1f, frontWidth * 0.85f, Color.black, b.id + "_SignText");
    }

    // ------------------------------------------------------------ props

    private static void BuildProps(GameObject root, LayoutData layout)
    {
        GameObject propsGo = new GameObject("Props");
        propsGo.transform.SetParent(root.transform, false);
        GameObject prefabNepa = LoadPrefab("NepaPole");
        GameObject prefabLamp = LoadPrefab("StreetLamp");
        GameObject prefabSoffit = LoadPrefab("SoffitLamp");
        GameObject prefabShelter = LoadPrefab("BusShelter");
        GameObject prefabBusStop = LoadPrefab("BusStopPole");
        GameObject prefabStreetSign = LoadPrefab("StreetSign");
        GameObject prefabGen = LoadPrefab("Generator");
        GameObject prefabKiosk = LoadPrefab("PosKiosk");
        GameObject prefabTree = LoadPrefab("TreeAlmond");
        GameObject prefabTyre = LoadPrefab("TyreStack");
        GameObject prefabCar = LoadPrefab("CarShell");
        GameObject prefabHoard = LoadPrefab("Hoarding");
        foreach (var p in layout.props)
        {
            switch (p.type)
            {
                case "nepa_pole": Place(p, propsGo, prefabNepa); break;
                case "street_lamp": Place(p, propsGo, prefabLamp, LampArmRotation(p)); break;
                case "soffit_lamp": Place(p, propsGo, prefabSoffit); break;
                case "bus_shelter":
                    Place(p, propsGo, prefabShelter);
                    if (!string.IsNullOrEmpty(p.sign))
                        AddSignTextChild(FindChild(propsGo, p.id), p.sign, new Vector3(0.85f, 2.4f, 0), 0.35f, 3.5f, Color.black, 90f);
                    break;
                case "bus_stop_pole":
                    Place(p, propsGo, prefabBusStop);
                    if (!string.IsNullOrEmpty(p.sign))
                        AddSignTextChild(FindChild(propsGo, p.id), p.sign, new Vector3(0, 2.6f, 0.1f), 0.2f, 0.65f, Color.white, 0f);
                    break;
                case "street_sign":
                    Place(p, propsGo, prefabStreetSign);
                    if (!string.IsNullOrEmpty(p.text))
                        AddSignTextChild(FindChild(propsGo, p.id), p.text, new Vector3(0, 2.85f, 0.1f), 0.22f, 0.85f, Color.white, 0f);
                    break;
                case "generator":
                    Place(p, propsGo, prefabGen, p.ry, GeneratorScale(p));
                    break;
                case "pos_kiosk":
                    Place(p, propsGo, prefabKiosk);
                    if (!string.IsNullOrEmpty(p.sign))
                        AddSignTextChild(FindChild(propsGo, p.id), p.sign, new Vector3(0, 1.35f, 1.1f), 0.4f, 1.5f, Color.white, 0f);
                    break;
                case "tree_almond": Place(p, propsGo, prefabTree); break;
                case "tyre_stack": Place(p, propsGo, prefabTyre); break;
                case "car_shell": Place(p, propsGo, prefabCar); break;
                case "hoarding":
                    Place(p, propsGo, prefabHoard);
                    if (!string.IsNullOrEmpty(p.text))
                        AddSignTextChild(FindChild(propsGo, p.id), p.text, new Vector3(0, 0.4f, 0.25f), 1.6f, 7.5f, Color.black, 0f);
                    break;
                case "guard_rail":
                    AddGuardRail(propsGo, p);
                    break;
                case "stall":
                    Place(p, propsGo, LoadPrefab(StallPrefabName(p.id)));
                    break;
                case "umbrella":
                    Place(p, propsGo, LoadPrefab(UmbrellaPrefabName(p.id)));
                    break;
                case "warden_marker":
                case "hawker_marker":
                    AddMarker(propsGo, p.id, new Vector3(p.x, p.y, p.z), p.ry);
                    break;
                default:
                    Debug.LogWarning("[OshodiGreybox] Unknown prop type '" + p.type + "' id=" + p.id + " — skipped");
                    break;
            }
        }
    }

    private static GameObject FindChild(GameObject parent, string name)
    {
        Transform t = parent.transform.Find(name);
        return t != null ? t.gameObject : null;
    }

    private static string StallPrefabName(string id)
    {
        if (id.Contains("-r2-")) return "StallBlue";
        if (id.Contains("-r3-")) return "StallYellow";
        return "StallRed";
    }

    // Umbrellas are red / blue / Lagos-yellow, cycled by number (spec 5).
    private static string UmbrellaPrefabName(string id)
    {
        int n = 0;
        string digits = "";
        foreach (char c in id) if (char.IsDigit(c)) digits += c;
        if (digits.Length > 0) n = int.Parse(digits);
        int m = (n - 1) % 3;
        if (m == 1) return "UmbrellaBlue";
        if (m == 2) return "UmbrellaYellow";
        return "UmbrellaRed";
    }

    // Generator instances carry w/d (0.6 x 1.2) against the prefab's 1.2 x 0.8.
    private static Vector3 GeneratorScale(PropData p)
    {
        if (p.w > 0 && p.d > 0) return new Vector3(p.w / 1.2f, 1f, p.d / 0.8f);
        return Vector3.one;
    }

    // Street lamp arms hang over the road. ROAD-A lamps (x=+/-8.75) point at
    // x=0; ROAD-B lamps (z=-65.55 / -74.45) point at z=-70.
    private static float LampArmRotation(PropData p)
    {
        if (Mathf.Abs(Mathf.Abs(p.x) - 8.75f) < 0.01f) return p.x < 0 ? 90f : 270f;
        if (Mathf.Abs(p.z + 65.55f) < 0.01f) return 180f;
        if (Mathf.Abs(p.z + 74.45f) < 0.01f) return 0f;
        return p.ry;
    }

    private static GameObject Place(PropData p, GameObject parent, GameObject prefab)
    {
        return Place(p, parent, prefab, p.ry, Vector3.one);
    }

    private static GameObject Place(PropData p, GameObject parent, GameObject prefab, float ry)
    {
        return Place(p, parent, prefab, ry, Vector3.one);
    }

    private static GameObject Place(PropData p, GameObject parent, GameObject prefab, float ry, Vector3 scale)
    {
        GameObject go = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
        go.name = p.id;
        go.transform.SetParent(parent.transform, false);
        go.transform.position = new Vector3(p.x, p.y, p.z);
        go.transform.rotation = Quaternion.Euler(0, ry, 0);
        go.transform.localScale = scale;
        return go;
    }

    // Guard rail run (median): posts every 3 m + 2 horizontal bars, 1.2 m high.
    // from/to are [x, z] pairs. One merged mesh + one box collider, Prop layer.
    private static void AddGuardRail(GameObject parent, PropData p)
    {
        if (p.from == null || p.to == null || p.from.Length < 2 || p.to.Length < 2)
        {
            Debug.LogWarning("[OshodiGreybox] guard_rail " + p.id + " has no from/to — skipped");
            return;
        }
        Vector3 a = new Vector3(p.from[0], 0, p.from[1]);
        Vector3 b = new Vector3(p.to[0], 0, p.to[1]);
        var go = new GameObject(p.id);
        go.transform.SetParent(parent.transform, false);
        var mb = new MeshBuilder();
        AddGuardRailRun(mb, a, b, 1.2f);
        SetMesh(go, mb.Build(p.id), GetMat("SteelDark"));
        go.layer = LayerProp;
        Vector3 mid = (a + b) * 0.5f;
        float len = Vector3.Distance(a, b);
        bool alongZ = Mathf.Abs(b.z - a.z) > Mathf.Abs(b.x - a.x);
        var c = go.AddComponent<BoxCollider>();
        c.center = new Vector3(mid.x, 0.6f, mid.z);
        c.size = alongZ ? new Vector3(0.15f, 1.2f, len) : new Vector3(len, 1.2f, 0.15f);
    }

    // Posts + 2 bars along a straight run at height h.
    private static void AddGuardRailRun(MeshBuilder mb, Vector3 a, Vector3 b, float h)
    {
        Vector3 dir = (b - a).normalized;
        float len = Vector3.Distance(a, b);
        for (float d = 0; d <= len; d += 3f)
        {
            Vector3 pos = a + dir * Mathf.Min(d, len);
            mb.AddBox(new Vector3(pos.x, h * 0.5f, pos.z), new Vector3(0.12f, h, 0.12f), 0, 0);
        }
        Vector3 mid = (a + b) * 0.5f;
        Quaternion rot = Quaternion.LookRotation(dir);
        mb.AddBox(new Vector3(mid.x, h * 0.55f, mid.z), new Vector3(0.08f, 0.08f, len), rot, 0);
        mb.AddBox(new Vector3(mid.x, h * 0.95f, mid.z), new Vector3(0.08f, 0.08f, len), rot, 0);
    }

    // Empty named GameObject with a gizmo, Marker layer (spec 8.5).
    private static GameObject AddMarker(GameObject parent, string id, Vector3 pos, float ry)
    {
        var go = new GameObject(id);
        go.transform.SetParent(parent.transform, false);
        go.transform.position = pos;
        go.transform.rotation = Quaternion.Euler(0, ry, 0);
        go.layer = LayerMarker;
        go.AddComponent<OshodiMarker>();
        return go;
    }

    // TextMeshPro sign as a child of a scale-1 prefab instance. localPos is in
    // the instance's local space; localRy rotates the text within the instance.
    // The text is on CameraIgnore (spec 8.3) and sized to fit targetHeight /
    // maxWidth in world units.
    private static void AddSignTextChild(GameObject parent, string text, Vector3 localPos, float targetHeight, float maxWidth, Color color, float localRy)
    {
        if (parent == null) return;
        var go = new GameObject("SignText");
        go.transform.SetParent(parent.transform, false);
        go.transform.localPosition = localPos;
        go.transform.localRotation = Quaternion.Euler(0, localRy, 0);
        go.layer = LayerCameraIgnore;
        var tmp = go.AddComponent<TextMeshPro>();
        SetupSignText(tmp, text, color);
        FitText(tmp, go, targetHeight, maxWidth);
    }

    // TextMeshPro sign in world space (for non-uniformly scaled instances).
    private static void AddSignTextWorld(GameObject parent, string text, Vector3 worldPos, float ry, float targetHeight, float maxWidth, Color color, string name)
    {
        var go = new GameObject(name);
        go.transform.SetParent(parent.transform, false);
        go.transform.position = worldPos;
        go.transform.rotation = Quaternion.Euler(0, ry, 0);
        go.layer = LayerCameraIgnore;
        var tmp = go.AddComponent<TextMeshPro>();
        SetupSignText(tmp, text, color);
        FitText(tmp, go, targetHeight, maxWidth);
    }

    private static void SetupSignText(TextMeshPro tmp, string text, Color color)
    {
        tmp.text = text;
        tmp.fontSize = 100;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.color = color;
        tmp.enableWordWrapping = false;
        tmp.rectTransform.sizeDelta = new Vector2(2000f, 300f);
        if (tmp.font == null)
        {
            var font = Resources.Load<TMP_FontAsset>("Fonts & Materials/LiberationSans SDF");
            if (font != null) tmp.font = font;
        }
    }

    private static void FitText(TextMeshPro tmp, GameObject go, float targetHeight, float maxWidth)
    {
        tmp.ForceMeshUpdate();
        Vector2 pref = tmp.GetPreferredValues();
        if (pref.y <= 0) return;
        float scale = targetHeight / pref.y;
        if (pref.x * scale > maxWidth) scale = maxWidth / pref.x;
        go.transform.localScale = Vector3.one * scale;
    }

    // ------------------------------------------------------------ danfo park

    private static void BuildDanfoPark(GameObject root, LayoutData layout)
    {
        var park = layout.danfoPark;
        GameObject parkGo = new GameObject("DanfoPark");
        parkGo.transform.SetParent(root.transform, false);
        GameObject prefabDanfo = LoadPrefab("Danfo");
        foreach (var d in park.danfos)
        {
            GameObject go = (GameObject)PrefabUtility.InstantiatePrefab(prefabDanfo);
            go.name = d.id;
            go.transform.SetParent(parkGo.transform, false);
            go.transform.position = new Vector3(d.x, 0, d.z);
            go.transform.rotation = Quaternion.Euler(0, d.ry, 0);
        }
        // Route boards (2.6 m pole, yellow and black) at each island tip.
        GameObject prefabBoard = LoadPrefab("RouteBoard");
        foreach (var rb in park.routeBoards)
        {
            GameObject go = (GameObject)PrefabUtility.InstantiatePrefab(prefabBoard);
            go.name = rb.id;
            go.transform.SetParent(parkGo.transform, false);
            go.transform.position = new Vector3(rb.x, 0, rb.z);
            go.transform.rotation = Quaternion.Euler(0, rb.ry, 0);
            AddSignTextChild(go, rb.text, new Vector3(0, 2.2f, 0.06f), 0.35f, 1.3f, Color.black, 0f);
        }
        // Conductor slots (M4 job slots): empty markers on the islands.
        foreach (var s in park.conductorSlots)
            AddMarker(parkGo, s.id, new Vector3(s.x, 0.12f, s.z), s.ry);
        // Park rail on the head-aisle edge (x=-14), 1.1 m, gaps at the crossings
        // and the exit driveway (from the JSON fence gaps).
        BuildParkRail(parkGo, park);
        // M4 bays: bay-N GameObjects with workPoint / aside / queue children.
        foreach (var bay in park.bays)
        {
            var bayGo = new GameObject(bay.id);
            bayGo.transform.SetParent(parkGo.transform, false);
            bayGo.layer = LayerMarker;
            AddMarker(bayGo, "workPoint", new Vector3(bay.workPoint.x, 0.12f, bay.workPoint.z), bay.workPoint.ry);
            foreach (var ap in bay.asidePoints)
                AddMarker(bayGo, ap.id, new Vector3(ap.x, 0.12f, ap.z), 0f);
            for (int i = 0; i < bay.queue.Length; i++)
                AddMarker(bayGo, "queue-" + (i + 1), new Vector3(bay.queue[i].x, 0.12f, bay.queue[i].z), 0f);
            // Door point (where the sliding door is) as a marker too.
            AddMarker(bayGo, "door", new Vector3(bay.door.x, 0.12f, bay.door.z), 0f);
        }
    }

    // Park rail segments = the fence run minus the JSON gaps. JsonUtility cannot
    // read the jagged gaps array, so the gaps are parsed from the raw JSON text.
    private static void BuildParkRail(GameObject parent, DanfoParkData park)
    {
        var gaps = ParseFenceGaps();
        var segments = new List<Vector2>();
        float cur = park.fence.z0;
        gaps.Sort((a, b) => a.x.CompareTo(b.x));
        foreach (var g in gaps)
        {
            if (g.x > cur + 0.01f) segments.Add(new Vector2(cur, g.x));
            cur = Mathf.Max(cur, g.y);
        }
        if (park.fence.z1 > cur + 0.01f) segments.Add(new Vector2(cur, park.fence.z1));
        var go = new GameObject(park.fence.id);
        go.transform.SetParent(parent.transform, false);
        var mb = new MeshBuilder();
        foreach (var s in segments)
            AddGuardRailRun(mb, new Vector3(park.fence.x, 0, s.x), new Vector3(park.fence.x, 0, s.y), park.fence.height);
        SetMesh(go, mb.Build(park.fence.id), GetMat("SteelDark"));
        go.layer = LayerProp;
        foreach (var s in segments)
        {
            var c = go.AddComponent<BoxCollider>();
            c.center = new Vector3(park.fence.x, park.fence.height * 0.5f, (s.x + s.y) * 0.5f);
            c.size = new Vector3(0.15f, park.fence.height, s.y - s.x);
        }
    }

    private static List<Vector2> ParseFenceGaps()
    {
        var gaps = new List<Vector2>();
        string full = Path.Combine(Application.dataPath, "../" + LayoutPath);
        string json = File.ReadAllText(full);
        int idx = json.IndexOf("\"gaps\"", StringComparison.Ordinal);
        if (idx < 0) return gaps;
        int start = json.IndexOf('[', idx);
        int end = json.IndexOf(']', json.IndexOf(']', start) + 1) + 1;
        if (start < 0 || end <= start) return gaps;
        string slice = json.Substring(start, end - start);
        var matches = System.Text.RegularExpressions.Regex.Matches(slice, @"-?\d+\.?\d*");
        for (int i = 0; i + 1 < matches.Count; i += 2)
            gaps.Add(new Vector2(float.Parse(matches[i].Value), float.Parse(matches[i + 1].Value)));
        return gaps;
    }

    // ------------------------------------------------------------ okada park

    private static void BuildOkadaPark(GameObject root, LayoutData layout)
    {
        var park = layout.okadaPark;
        GameObject parkGo = new GameObject("OkadaPark");
        parkGo.transform.SetParent(root.transform, false);
        GameObject prefabOkada = LoadPrefab("Okada");
        foreach (var b in park.bikes)
        {
            GameObject go = (GameObject)PrefabUtility.InstantiatePrefab(prefabOkada);
            go.name = b.id;
            go.transform.SetParent(parkGo.transform, false);
            go.transform.position = new Vector3(b.x, 0, b.z);
            go.transform.rotation = Quaternion.Euler(0, b.ry, 0);
        }
        foreach (var s in park.riderSlots)
            AddMarker(parkGo, s.id, new Vector3(s.x, 0, s.z), s.ry);
    }

    // ------------------------------------------------------------ flyover

    private static void BuildFlyover(GameObject root, LayoutData layout)
    {
        var fly = layout.flyover;
        GameObject flyGo = new GameObject("Flyover");
        flyGo.transform.SetParent(root.transform, false);
        Rect deck = fly.deck;
        float cx = (deck.x0 + deck.x1) * 0.5f;
        float cz = (deck.z0 + deck.z1) * 0.5f;
        float w = deck.x1 - deck.x0;
        float d = deck.z1 - deck.z0;
        // Deck (underside 6.0, top 7.2). Not reachable in M2: a PlayerBlocker
        // above it stops anything from landing there.
        var mb = new MeshBuilder();
        mb.AddBox(new Vector3(cx, (fly.undersideY + fly.deckTopY) * 0.5f, cz),
            new Vector3(w, fly.deckTopY - fly.undersideY, d), 0, 0);
        // Parapets 1.0 m on both long edges.
        mb.AddBox(new Vector3(cx, fly.deckTopY + fly.parapetHeight * 0.5f, deck.z0 + 0.15f),
            new Vector3(w, fly.parapetHeight, 0.3f), 0, 1);
        mb.AddBox(new Vector3(cx, fly.deckTopY + fly.parapetHeight * 0.5f, deck.z1 - 0.15f),
            new Vector3(w, fly.parapetHeight, 0.3f), 0, 1);
        var deckGo = new GameObject(fly.id);
        deckGo.transform.SetParent(flyGo.transform, false);
        SetMesh(deckGo, mb.Build(fly.id), GetMat("FlyoverDeck"), GetMat("FlyoverBarrier"));
        deckGo.layer = LayerBuilding;
        AddBoxCollider(deckGo, new Vector3(cx, (fly.undersideY + fly.deckTopY) * 0.5f, cz),
            new Vector3(w, fly.deckTopY - fly.undersideY, d));
        // Blocker above the deck (invisible, PlayerBlocker).
        var blocker = new GameObject(fly.id + "_Blocker");
        blocker.transform.SetParent(flyGo.transform, false);
        blocker.layer = LayerPlayerBlocker;
        var bc = blocker.AddComponent<BoxCollider>();
        bc.center = new Vector3(cx, fly.deckTopY + 2f, cz);
        bc.size = new Vector3(w, 4f, d);
        // Piers: 1.2 m round columns, 6 m high.
        GameObject prefabPier = LoadPrefab("FlyoverPier");
        foreach (var p in fly.piers)
        {
            GameObject go = (GameObject)PrefabUtility.InstantiatePrefab(prefabPier);
            go.name = p.id;
            go.transform.SetParent(flyGo.transform, false);
            go.transform.position = new Vector3(p.x, p.height * 0.5f, p.z);
            go.transform.localScale = new Vector3(p.diameter, p.height, p.diameter);
            // Two posters each on the +/-14 piers, facing the pavements (+/-X).
            if (p.posters > 0)
            {
                AddPoster(flyGo, p.id, new Vector3(p.x + p.diameter * 0.5f + 0.02f, 1.5f, p.z), 90f);
                if (p.posters > 1)
                    AddPoster(flyGo, p.id, new Vector3(p.x - p.diameter * 0.5f - 0.02f, 1.5f, p.z), 270f);
            }
        }
    }

    private static void AddPoster(GameObject parent, string pierId, Vector3 pos, float ry)
    {
        GameObject prefab = LoadPrefab("Poster");
        GameObject go = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
        go.name = "Poster_" + pierId + "_" + ((int)ry);
        go.transform.SetParent(parent.transform, false);
        go.transform.position = pos;
        go.transform.rotation = Quaternion.Euler(0, ry, 0);
    }

    // ------------------------------------------------------------ footbridge

    private static void BuildFootbridge(GameObject root, LayoutData layout)
    {
        var fb = layout.footbridge;
        GameObject fbGo = new GameObject("Footbridge");
        fbGo.transform.SetParent(root.transform, false);
        Rect deck = fb.deck;
        float dcx = (deck.x0 + deck.x1) * 0.5f;
        float dcz = (deck.z0 + deck.z1) * 0.5f;
        float dw = deck.x1 - deck.x0;
        float dd = deck.z1 - deck.z0;
        // Deck slab (underside 5.72, top 6.12), Ground layer (walkable).
        var mb = new MeshBuilder();
        mb.AddBox(new Vector3(dcx, (fb.undersideY + fb.deckTopY) * 0.5f, dcz),
            new Vector3(dw, fb.deckTopY - fb.undersideY, dd), 0, 0);
        // Parapets 1.1 m on both long edges, with banner panels on the outer faces.
        mb.AddBox(new Vector3(dcx, fb.deckTopY + fb.parapetHeight * 0.5f, deck.z0 + 0.075f),
            new Vector3(dw, fb.parapetHeight, 0.15f), 0, 1);
        mb.AddBox(new Vector3(dcx, fb.deckTopY + fb.parapetHeight * 0.5f, deck.z1 - 0.075f),
            new Vector3(dw, fb.parapetHeight, 0.15f), 0, 1);
        mb.AddBox(new Vector3(dcx, fb.deckTopY + 0.55f, deck.z0 - 0.03f),
            new Vector3(dw * 0.9f, 0.8f, 0.05f), 0, 2);
        mb.AddBox(new Vector3(dcx, fb.deckTopY + 0.55f, deck.z1 + 0.03f),
            new Vector3(dw * 0.9f, 0.8f, 0.05f), 0, 2);
        var deckGo = new GameObject(fb.id + "_Deck");
        deckGo.transform.SetParent(fbGo.transform, false);
        SetMesh(deckGo, mb.Build(fb.id + "_Deck"), GetMat("FlyoverDeck"), GetMat("FlyoverBarrier"), GetMat("SignWhite"));
        deckGo.layer = LayerGround;
        AddBoxCollider(deckGo, new Vector3(dcx, (fb.undersideY + fb.deckTopY) * 0.5f, dcz),
            new Vector3(dw, fb.deckTopY - fb.undersideY, dd));
        // Stairs at both ends (two flights + mid landing + top landing each).
        foreach (var stair in fb.stairs)
            BuildFootbridgeStair(fbGo, fb, stair);
        // Piers: four 0.4 m square columns under the top landings, 1 poster each
        // facing the road.
        foreach (var p in fb.piers)
        {
            var pierGo = new GameObject(p.id);
            pierGo.transform.SetParent(fbGo.transform, false);
            pierGo.transform.position = new Vector3(p.x, p.height * 0.5f, p.z);
            var pmb = new MeshBuilder();
            pmb.AddBox(Vector3.zero, new Vector3(p.size, p.height, p.size), Quaternion.identity, 0);
            SetMesh(pierGo, pmb.Build(p.id), GetMat("Concrete"));
            pierGo.layer = LayerBuilding;
            AddBoxCollider(pierGo, Vector3.zero, new Vector3(p.size, p.height, p.size));
            if (p.posters > 0)
            {
                float ry = p.x < 0 ? 90f : 270f; // face the road (ROAD-A, x=0)
                float fx = p.x < 0 ? p.x + p.size * 0.5f + 0.02f : p.x - p.size * 0.5f - 0.02f;
                AddPoster(fbGo, p.id, new Vector3(fx, 1.5f, p.z), ry);
            }
        }
    }

    private static void BuildFootbridgeStair(GameObject parent, FootbridgeData fb, FootbridgeStairData stair)
    {
        var stairGo = new GameObject(stair.id);
        stairGo.transform.SetParent(parent.transform, false);
        bool west = stair.footprint.x1 < 0; // west stair descends toward -X
        float z0 = stair.footprint.z0, z1 = stair.footprint.z1;
        float zc = (z0 + z1) * 0.5f, zd = z1 - z0;
        // Visual steps (flight 1: open thin slab; flight 2: solid from ground).
        var mb = new MeshBuilder();
        AddStairFlightSteps(mb, stair.flight1, west, false, 0);
        AddStairFlightSteps(mb, stair.flight2, west, true, 0);
        // Mid landing: solid box from the ground to its top.
        mb.AddRectBox(stair.midLanding.r, 0f, stair.midLanding.y, 0);
        // Top landing: flat slab (same thickness as the deck).
        mb.AddRectBox(stair.topLanding.r, fb.undersideY, fb.deckTopY, 0);
        SetMesh(stairGo, mb.Build(stair.id), GetMat("FlyoverDeck"));
        stairGo.layer = LayerGround;
        // Walk colliders (spec 4.2): one smooth sloped ramp per flight, Ground
        // layer; steps are visual only. Flight 2's ramp is thick (3 m) so the
        // closed-under space beneath it is solid; flight 1's is thin (open under).
        AddStairRamp(stairGo, stair.flight1, west, 0.2f, zc, zd);
        AddStairRamp(stairGo, stair.flight2, west, 3.0f, zc, zd);
        // Landing colliders (flat, Ground layer).
        AddGroundBox(stairGo, (stair.midLanding.r.x0 + stair.midLanding.r.x1) * 0.5f, stair.midLanding.y,
            (stair.midLanding.r.z0 + stair.midLanding.r.z1) * 0.5f,
            stair.midLanding.r.x1 - stair.midLanding.r.x0, stair.midLanding.y, stair.midLanding.r.z1 - stair.midLanding.r.z0);
        AddGroundBox(stairGo, (stair.topLanding.r.x0 + stair.topLanding.r.x1) * 0.5f, stair.topLanding.y,
            (stair.topLanding.r.z0 + stair.topLanding.r.z1) * 0.5f,
            stair.topLanding.r.x1 - stair.topLanding.r.x0, fb.deckTopY - fb.undersideY, stair.topLanding.r.z1 - stair.topLanding.r.z0);
        // Side railings along each flight (visual + collider, 1.1 m high).
        AddStairRailings(stairGo, stair.flight1, west, z0, z1);
        AddStairRailings(stairGo, stair.flight2, west, z0, z1);
    }

    // Visual steps for one flight. West stairs descend toward -X (top at x1);
    // east stairs descend toward +X (top at x0). Flight 1 is an open thin slab
    // (0.3 thick); flight 2 is solid from the ground (closed under, spec 4.2).
    private static void AddStairFlightSteps(MeshBuilder mb, StairFlightData flight, bool west, bool solid, int mat)
    {
        float run = flight.r.x1 - flight.r.x0;
        float tread = run / flight.risers;
        float riser = (flight.yTop - flight.yBottom) / flight.risers;
        for (int i = 0; i < flight.risers; i++)
        {
            float x0, x1;
            if (west) { x1 = flight.r.x1 - i * tread; x0 = x1 - tread; }
            else { x0 = flight.r.x0 + i * tread; x1 = x0 + tread; }
            float top = flight.yTop - i * riser;
            float y0 = solid ? 0f : top - 0.3f;
            mb.AddBox(new Vector3((x0 + x1) * 0.5f, (y0 + top) * 0.5f, (flight.r.z0 + flight.r.z1) * 0.5f),
                new Vector3(tread, top - y0, flight.r.z1 - flight.r.z0), mat);
        }
    }

    // One smooth sloped BoxCollider per flight (the walk surface). The box's top
    // face sits on the slope line; its thickness extends downward. Angle is
    // about 32 degrees (under the 45 slope limit).
    private static void AddStairRamp(GameObject parent, StairFlightData flight, bool west, float thickness, float zc, float zd)
    {
        float run = flight.r.x1 - flight.r.x0;
        float rise = flight.yTop - flight.yBottom;
        float len = Mathf.Sqrt(run * run + rise * rise);
        float angle = Mathf.Atan2(rise, run) * Mathf.Rad2Deg;
        float xc = (flight.r.x0 + flight.r.x1) * 0.5f;
        float yc = (flight.yTop + flight.yBottom) * 0.5f;
        var go = new GameObject("Ramp_" + flight.r.x0.ToString("F1") + "_" + flight.r.x1.ToString("F1"));
        go.transform.SetParent(parent.transform, false);
        go.transform.position = new Vector3(xc, yc, zc);
        go.transform.rotation = Quaternion.Euler(0, 0, west ? angle : -angle);
        go.layer = LayerGround;
        var c = go.AddComponent<BoxCollider>();
        c.center = new Vector3(0, -thickness * 0.5f, 0);
        c.size = new Vector3(len + 0.1f, thickness, zd);
    }

    // Sloped railings on both sides of a flight (visual boxes + thin colliders).
    private static void AddStairRailings(GameObject parent, StairFlightData flight, bool west, float z0, float z1)
    {
        float run = flight.r.x1 - flight.r.x0;
        float rise = flight.yTop - flight.yBottom;
        float len = Mathf.Sqrt(run * run + rise * rise);
        float angle = Mathf.Atan2(rise, run) * Mathf.Rad2Deg;
        float xc = (flight.r.x0 + flight.r.x1) * 0.5f;
        float yc = (flight.yTop + flight.yBottom) * 0.5f + 0.55f;
        foreach (float z in new[] { z0 + 0.08f, z1 - 0.08f })
        {
            var go = new GameObject("Railing_" + z.ToString("F1"));
            go.transform.SetParent(parent.transform, false);
            go.transform.position = new Vector3(xc, yc, z);
            go.transform.rotation = Quaternion.Euler(0, 0, west ? angle : -angle);
            go.layer = LayerBuilding;
            var mb = new MeshBuilder();
            mb.AddBox(Vector3.zero, new Vector3(len, 1.1f, 0.08f), Quaternion.identity, 0);
            SetMesh(go, mb.Build("Railing"), GetMat("FlyoverBarrier"));
            AddBoxCollider(go, Vector3.zero, new Vector3(len, 1.1f, 0.08f));
        }
    }

    // ------------------------------------------------------------ wires

    private static void BuildWires(GameObject root, LayoutData layout)
    {
        GameObject wireGo = new GameObject("Wires");
        wireGo.transform.SetParent(root.transform, false);
        var mb = new MeshBuilder();
        foreach (var w in layout.wires)
        {
            Vector3 a = new Vector3(w.from[0], w.topY, w.from[1]);
            Vector3 b = new Vector3(w.to[0], w.topY, w.to[1]);
            Vector3 dir = (b - a).normalized;
            Vector3 side = new Vector3(-dir.z, 0, dir.x);
            float ctrlY = 2f * w.sagY - w.topY;
            for (int s = 0; s < w.strands; s++)
            {
                float off = (s - (w.strands - 1) * 0.5f) * 0.15f;
                Vector3 ao = a + side * off;
                Vector3 bo = b + side * off;
                Vector3 ctrl = (ao + bo) * 0.5f;
                ctrl.y = ctrlY;
                AddQuadraticBezier(mb, ao, ctrl, bo, 0, 10);
            }
        }
        var go = new GameObject("WireMesh");
        go.transform.SetParent(wireGo.transform, false);
        SetMesh(go, mb.Build("WireMesh"), GetMat("Wire"));
        go.layer = LayerCameraIgnore;
    }

    // ------------------------------------------------------------ skyline

    // One merged mesh (one draw call): a ring of flat building silhouettes at
    // about 350 m (inside the 380 m fog end, so it reads as haze), plus a
    // cluster of glass towers to the south-east (Victoria Island, lit at night).
    // Never collides, CameraIgnore (spec 6.5).
    private static void BuildSkyline(GameObject root, Vector3 centre, float radius)
    {
        GameObject skyGo = new GameObject("Skyline");
        skyGo.transform.SetParent(root.transform, false);
        var mb = new MeshBuilder();
        var rng = new System.Random(20261105);
        int count = 28;
        for (int i = 0; i < count; i++)
        {
            float angle = (float)i / count * 360f + (float)rng.NextDouble() * 8f;
            float w = 20f + (float)rng.NextDouble() * 30f;
            float h = 25f + (float)rng.NextDouble() * 45f;
            float d = 15f + (float)rng.NextDouble() * 20f;
            float x = centre.x + Mathf.Sin(angle * Mathf.Deg2Rad) * radius;
            float z = centre.z + Mathf.Cos(angle * Mathf.Deg2Rad) * radius;
            // Keep the ring off the approach road (district: skip the due-south
            // silhouettes that would stand on the corridor) and out of the
            // tile (approach: skip the due-north silhouettes inside z>-160).
            if (centre.z > -100f && Mathf.Abs(x) < 25f && z < -150f) continue;
            if (centre.z < -100f && z > -160f) continue;
            mb.AddBox(new Vector3(x, h * 0.5f, z), new Vector3(w, h, d), Quaternion.Euler(0, angle, 0), 0);
        }
        // South-east glass tower cluster (Victoria Island across the water).
        for (int i = 0; i < 8; i++)
        {
            float x = centre.x + 200f + (float)rng.NextDouble() * 120f;
            float z = centre.z - 220f - (float)rng.NextDouble() * 80f;
            float w = 18f + (float)rng.NextDouble() * 15f;
            float h = 60f + (float)rng.NextDouble() * 60f;
            float d = 18f + (float)rng.NextDouble() * 15f;
            mb.AddBox(new Vector3(x, h * 0.5f, z), new Vector3(w, h, d), Quaternion.Euler(0, (float)rng.NextDouble() * 30f, 0), 1);
        }
        var go = new GameObject("SkylineShell");
        go.transform.SetParent(skyGo.transform, false);
        SetMesh(go, mb.Build("SkylineShell"), GetMat("Skyline"), GetMat("Glass"));
        go.layer = LayerCameraIgnore;
    }

    // ------------------------------------------------------------ blockers

    // Invisible PlayerBlocker walls, 4 m high (spec 2): around the tile edge,
    // with the roads carrying on 10 m past the edge before their wall.
    private static void BuildBlockers(GameObject root, LayoutData layout)
    {
        GameObject blkGo = new GameObject("Blockers");
        blkGo.transform.SetParent(root.transform, false);
        Rect tile = layout.tile;
        AddBlockerWall(blkGo, "Blocker_North_West", new Vector3((tile.x0 - 7.7f) * 0.5f, 2f, tile.z1), new Vector3(-7.7f - tile.x0, 4f, 0.5f));
        AddBlockerWall(blkGo, "Blocker_North_East", new Vector3((7.7f + tile.x1) * 0.5f, 2f, tile.z1), new Vector3(tile.x1 - 7.7f, 4f, 0.5f));
        AddBlockerWall(blkGo, "Blocker_South_West", new Vector3((tile.x0 - 7.7f) * 0.5f, 2f, tile.z0), new Vector3(-7.7f - tile.x0, 4f, 0.5f));
        AddBlockerWall(blkGo, "Blocker_South_East", new Vector3((7.7f + tile.x1) * 0.5f, 2f, tile.z0), new Vector3(tile.x1 - 7.7f, 4f, 0.5f));
        AddBlockerWall(blkGo, "Blocker_West_North", new Vector3(tile.x0, 2f, (-66.6f + tile.z1) * 0.5f), new Vector3(0.5f, 4f, tile.z1 + 66.6f));
        AddBlockerWall(blkGo, "Blocker_West_South", new Vector3(tile.x0, 2f, (tile.z0 - 73.4f) * 0.5f), new Vector3(0.5f, 4f, -73.4f - tile.z0));
        AddBlockerWall(blkGo, "Blocker_East_North", new Vector3(tile.x1, 2f, (-66.6f + tile.z1) * 0.5f), new Vector3(0.5f, 4f, tile.z1 + 66.6f));
        AddBlockerWall(blkGo, "Blocker_East_South", new Vector3(tile.x1, 2f, (tile.z0 - 73.4f) * 0.5f), new Vector3(0.5f, 4f, -73.4f - tile.z0));
        // Road-end walls (10 m past the tile edge).
        AddBlockerWall(blkGo, "Blocker_RoadA_North", new Vector3(0, 2f, 160f), new Vector3(15.4f, 4f, 0.5f));
        AddBlockerWall(blkGo, "Blocker_RoadA_South", new Vector3(0, 2f, -160f), new Vector3(15.4f, 4f, 0.5f));
        AddBlockerWall(blkGo, "Blocker_RoadB_West", new Vector3(-130f, 2f, -70f), new Vector3(0.5f, 4f, 6.8f));
        AddBlockerWall(blkGo, "Blocker_RoadB_East", new Vector3(130f, 2f, -70f), new Vector3(0.5f, 4f, 6.8f));
    }

    private static void AddBlockerWall(GameObject parent, string name, Vector3 centre, Vector3 size)
    {
        var go = new GameObject(name);
        go.transform.SetParent(parent.transform, false);
        go.layer = LayerPlayerBlocker;
        var c = go.AddComponent<BoxCollider>();
        c.center = centre;
        c.size = size;
    }

    // ------------------------------------------------------------ markers

    private static void BuildMarkers(GameObject root, LayoutData layout)
    {
        GameObject markersGo = new GameObject("Markers");
        markersGo.transform.SetParent(root.transform, false);
        AddMarker(markersGo, "Spawn_Player", new Vector3(layout.spawn.x, layout.spawn.y, layout.spawn.z), layout.spawn.ry);
        foreach (var v in layout.viewpoints)
            AddMarker(markersGo, v.id, new Vector3(v.x, v.y, v.z), v.ry);
    }

    // ------------------------------------------------------------ approach scene

    private static void BuildApproach(GameObject root, LayoutData layout)
    {
        var app = layout.approach;
        // Base plane under the corridor (dirt, top y=-0.02).
        var baseMb = new MeshBuilder();
        baseMb.AddBox(new Vector3(0, -0.51f, -475f), new Vector3(120f, 1f, 750f), 0, 0);
        var baseGo = new GameObject("GroundBase");
        baseGo.transform.SetParent(root.transform, false);
        SetMesh(baseGo, baseMb.Build("ApproachGroundBase"), GetMat("Dirt"));
        baseGo.layer = LayerGround;
        AddGroundBox(baseGo, 0, -0.02f, -475f, 120f, 1f, 750f);

        // Road (asphalt, top y=0): the two lanes, the connector to the
        // roundabout, the roundabout disc, the stub south of it.
        var roadMb = new MeshBuilder();
        var roadGo = new GameObject("Roads");
        roadGo.transform.SetParent(root.transform, false);
        foreach (var lane in app.lanes)
        {
            roadMb.AddRectBox(lane.r, -0.5f, 0f, 0);
            AddGroundBox(roadGo, (lane.r.x0 + lane.r.x1) * 0.5f, 0f, (lane.r.z0 + lane.r.z1) * 0.5f,
                lane.r.x1 - lane.r.x0, 0.5f, lane.r.z1 - lane.r.z0);
        }
        // Connector between the lanes (z=-700) and the roundabout ring (z=-704).
        roadMb.AddRectBox(new Rect { x0 = -7.55f, z0 = -704f, x1 = 7.55f, z1 = -700f }, -0.5f, 0f, 0);
        AddGroundBox(roadGo, 0, 0f, -702f, 15.1f, 0.5f, 4f);
        roadMb.AddRectBox(app.stubSouth, -0.5f, 0f, 0);
        AddGroundBox(roadGo, (app.stubSouth.x0 + app.stubSouth.x1) * 0.5f, 0f, (app.stubSouth.z0 + app.stubSouth.z1) * 0.5f,
            app.stubSouth.x1 - app.stubSouth.x0, 0.5f, app.stubSouth.z1 - app.stubSouth.z0);
        SetMesh(roadGo, roadMb.Build("ApproachRoads"), GetMat("Asphalt"));
        roadGo.layer = LayerGround;

        // Roundabout: drivable ring (asphalt disc r=16) + island (cylinder r=9,
        // kerb 0.12). Island collider is a MeshCollider (cylinder, L-125).
        var rb = app.roundabout;
        Vector3 rbCentre = new Vector3(rb.centre[0], 0, rb.centre[1]);
        var ringGo = new GameObject(rb.id);
        ringGo.transform.SetParent(root.transform, false);
        Mesh disc = BuildCylinderMesh(rb.ringOuterRadius * 2f, 0.1f, 24);
        var dmf = ringGo.AddComponent<MeshFilter>(); dmf.sharedMesh = disc;
        var dmr = ringGo.AddComponent<MeshRenderer>(); dmr.sharedMaterial = GetMat("Asphalt");
        dmr.receiveShadows = true;
        ringGo.isStatic = true;
        ringGo.layer = LayerGround;
        // Disc mesh is centred at origin (spans -0.05..0.05), so the GameObject
        // sits at y=-0.05 for a top at y=0; the collider is centred in local
        // space (0,0,0) to match.
        ringGo.transform.position = new Vector3(rbCentre.x, -0.05f, rbCentre.z);
        var ringCol = ringGo.AddComponent<BoxCollider>();
        ringCol.center = Vector3.zero;
        ringCol.size = new Vector3(rb.ringOuterRadius * 2f, 0.1f, rb.ringOuterRadius * 2f);
        var islandGo = new GameObject(rb.id + "_Island");
        islandGo.transform.SetParent(root.transform, false);
        islandGo.transform.position = new Vector3(rbCentre.x, rb.kerbHeight * 0.5f, rbCentre.z);
        Mesh islandMesh = BuildCylinderMesh(rb.islandRadius * 2f, rb.kerbHeight, 24);
        var imf = islandGo.AddComponent<MeshFilter>(); imf.sharedMesh = islandMesh;
        var imr = islandGo.AddComponent<MeshRenderer>(); imr.sharedMaterial = GetMat("Sidewalk");
        imr.receiveShadows = true;
        islandGo.isStatic = true;
        islandGo.layer = LayerGround;
        var mc = islandGo.AddComponent<MeshCollider>();
        mc.sharedMesh = islandMesh;
        mc.convex = false;

        // Median (raised 0.12) + guard rail along the approach lanes.
        var kerbMb = new MeshBuilder();
        var kerbGo = new GameObject("Kerbs");
        kerbGo.transform.SetParent(root.transform, false);
        kerbMb.AddRectBox(new Rect { x0 = -1.05f, z0 = -700f, x1 = 1.05f, z1 = -150f }, 0f, 0.12f, 0);
        AddGroundBox(kerbGo, 0, 0.12f, -425f, 2.1f, 0.12f, 550f);
        kerbMb.AddRectBox(new Rect { x0 = -7.7f, z0 = -700f, x1 = -7.55f, z1 = -150f }, 0f, 0.12f, 0);
        kerbMb.AddRectBox(new Rect { x0 = 7.55f, z0 = -700f, x1 = 7.7f, z1 = -150f }, 0f, 0.12f, 0);
        SetMesh(kerbGo, kerbMb.Build("ApproachKerbs"), GetMat("Kerb"));
        kerbGo.layer = LayerGround;
        var railGo = new GameObject("GuardRail_Median");
        railGo.transform.SetParent(root.transform, false);
        var railMb = new MeshBuilder();
        AddGuardRailRun(railMb, new Vector3(0, 0, -700f), new Vector3(0, 0, -150f), 1.2f);
        SetMesh(railGo, railMb.Build("ApproachGuardRail"), GetMat("SteelDark"));
        railGo.layer = LayerProp;
        var rc = railGo.AddComponent<BoxCollider>();
        rc.center = new Vector3(0, 0.6f, -425f);
        rc.size = new Vector3(0.15f, 1.2f, 550f);

        // Pavements (Sidewalk, top y=0.12) both sides. The west pavement steps
        // out around the lay-by and keeps 3.5 m (spec 4.6).
        var paveMb = new MeshBuilder();
        var paveGo = new GameObject("Pavements");
        paveGo.transform.SetParent(root.transform, false);
        var ds = app.dropStop;
        // West pavement: north of the lay-by, around it, south of it.
        paveMb.AddRectBox(new Rect { x0 = -11.2f, z0 = -637f, x1 = -7.7f, z1 = -150f }, 0f, 0.12f, 0);
        paveMb.AddRectBox(new Rect { x0 = -14.05f, z0 = -655f, x1 = -10.55f, z1 = -637f }, 0f, 0.12f, 0);
        paveMb.AddRectBox(new Rect { x0 = -11.2f, z0 = -700f, x1 = -7.7f, z1 = -655f }, 0f, 0.12f, 0);
        // East pavement.
        paveMb.AddRectBox(new Rect { x0 = 7.7f, z0 = -700f, x1 = 11.2f, z1 = -150f }, 0f, 0.12f, 0);
        SetMesh(paveGo, paveMb.Build("ApproachPavements"), GetMat("Sidewalk"));
        paveGo.layer = LayerGround;
        AddGroundBox(paveGo, -9.45f, 0.12f, -393.5f, 3.5f, 0.12f, 487f);
        AddGroundBox(paveGo, -12.3f, 0.12f, -646f, 3.5f, 0.12f, 18f);
        AddGroundBox(paveGo, -9.45f, 0.12f, -677.5f, 3.5f, 0.12f, 45f);
        AddGroundBox(paveGo, 9.45f, 0.12f, -425f, 3.5f, 0.12f, 550f);

        // Drop stop: lay-by (asphalt, cut into the west verge), shelter behind
        // the pavement, stop + alight markers.
        var layGo = new GameObject(ds.id);
        layGo.transform.SetParent(root.transform, false);
        var layMb = new MeshBuilder();
        layMb.AddRectBox(ds.layBy, -0.5f, 0f, 0);
        SetMesh(layGo, layMb.Build(ds.id), GetMat("Asphalt"));
        layGo.layer = LayerGround;
        AddGroundBox(layGo, (ds.layBy.x0 + ds.layBy.x1) * 0.5f, 0f, (ds.layBy.z0 + ds.layBy.z1) * 0.5f,
            ds.layBy.x1 - ds.layBy.x0, 0.5f, ds.layBy.z1 - ds.layBy.z0);
        GameObject prefabShelter = LoadPrefab("BusShelter");
        GameObject shelterGo = (GameObject)PrefabUtility.InstantiatePrefab(prefabShelter);
        shelterGo.name = ds.id + "_Shelter";
        shelterGo.transform.SetParent(root.transform, false);
        shelterGo.transform.position = new Vector3(ds.shelter.x, 0, ds.shelter.z);
        shelterGo.transform.rotation = Quaternion.Euler(0, 0, 0);
        AddMarker(root, "drop-stop-point", new Vector3(ds.stopPoint.x, 0, ds.stopPoint.z), ds.stopPoint.ry);
        AddMarker(root, "drop-alight-point", new Vector3(ds.alightPoint.x, 0.12f, ds.alightPoint.z), 0f);

        // End barrier at z=-799: solid barrier + fence across the road end.
        var endGo = new GameObject("EndBarrier");
        endGo.transform.SetParent(root.transform, false);
        var endMb = new MeshBuilder();
        endMb.AddBox(new Vector3(0, 1f, app.endBarrier.z), new Vector3(15.1f, 2f, 0.4f), 0, 0);
        endMb.AddBox(new Vector3(0, 1f, app.endBarrier.z), new Vector3(22.4f, 2f, 0.15f), 0, 1);
        SetMesh(endGo, endMb.Build("EndBarrier"), GetMat("FlyoverBarrier"), GetMat("SteelDark"));
        endGo.layer = LayerPlayerBlocker;
        var ec = endGo.AddComponent<BoxCollider>();
        ec.center = new Vector3(0, 1f, app.endBarrier.z);
        ec.size = new Vector3(22.4f, 2f, 0.5f);

        // Skyline ring centred on the approach corridor (so it never sits on
        // the road), plus the streaming test start marker.
        BuildSkyline(root, new Vector3(0, 0, -475f), 350f);
        AddMarker(root, "streaming-test-start",
            new Vector3(app.streamingTestStart.x, app.streamingTestStart.y, app.streamingTestStart.z),
            app.streamingTestStart.ry);

        // Corridor side blockers (invisible, 4 m high); the north end (z=-150)
        // stays open into the tile.
        GameObject blkGo = new GameObject("Blockers");
        blkGo.transform.SetParent(root.transform, false);
        AddBlockerWall(blkGo, "Blocker_West", new Vector3(-11.2f, 2f, -475f), new Vector3(0.5f, 4f, 650f));
        AddBlockerWall(blkGo, "Blocker_East", new Vector3(11.2f, 2f, -475f), new Vector3(0.5f, 4f, 650f));
    }
}
